-- Self-referencing table(s): 'WI_BKGS_MSR_ATY_SW_PRDT_XAAS' used as both source and target in this mapping.
-- Materialized as TABLE to snapshot source data before the target model overwrites it.
SELECT
	MT.BOOKINGS_MEASURE_KEY,
	MT.BKGS_MEASURE_TRANS_TYPE_CODE,
	MT.BOOKINGS_PROCESS_DATE,
	MT.SALES_TERRITORY_KEY,
	MT.SALES_REP_NUMBER,
	MT.DV_CONTRACT_DURATION,
	MT.DV_ANNUALIZED_FLG,
	MT.RU_SERVICE_CONTRACT_START_DTM,
	MT.RU_SERVICE_CONTRACT_END_DTM,
	MT.ANNUITY_TYPE,
	MT.ANNUITY_MONTH,
	MT.ANNUITY_WEEK,
MT.BKGS_END_WEEK,
	MT.PER_MONTH_AMT  *12   ANNUITY_AMT  /*SVAKULAB*/,
	MT.DV_FMV_FLG,
	MT.ADJUSTMENT_CODE,
	MT.ACQUISITION_ORDER_ORIGIN_CD,
MT.ACQUISITION_ROLE
	FROM
	{{ source('raw', 'WI_BKGS_MSR_ATY_PRDT_AMR_XAAS') }} MT
	WHERE
	RTRIM(  ANNUITY_TYPE)  in (COLLATE('Software', 'en-ci-rtrim'))
AND (BOOKINGS_MEASURE_KEY, BKGS_MEASURE_TRANS_TYPE_CODE, BOOKINGS_PROCESS_DATE, COLLATE(ANNUITY_TYPE, 'en-ci-rtrim'), SALES_TERRITORY_KEY, SALES_REP_NUMBER, ANNUITY_MONTH)
NOT IN (
		SELECT
			BOOKINGS_MEASURE_KEY,
			BKGS_MEASURE_TRANS_TYPE_CODE,
			BOOKINGS_PROCESS_DATE,
			COLLATE(ANNUITY_TYPE, 'en-ci-rtrim'),
			SALES_TERRITORY_KEY,
			SALES_REP_NUMBER,
			MAX(ANNUITY_MONTH)  ANNUITY_MONTH
							FROM
			{{ source('raw', 'WI_BKGS_MSR_ATY_PRDT_AMR_XAAS') }}
		WHERE
			RTRIM( ANNUITY_TYPE)  in (COLLATE('Software', 'en-ci-rtrim'))
							GROUP BY BOOKINGS_MEASURE_KEY  ,BKGS_MEASURE_TRANS_TYPE_CODE  ,BOOKINGS_PROCESS_DATE,SALES_TERRITORY_KEY,SALES_REP_NUMBER,ANNUITY_TYPE )
			UNION ALL
			SELECT
	MT.BOOKINGS_MEASURE_KEY,
	MT.BKGS_MEASURE_TRANS_TYPE_CODE,
	MT.BOOKINGS_PROCESS_DATE,
	MT.SALES_TERRITORY_KEY,
	MT.SALES_REP_NUMBER,
	MT.DV_CONTRACT_DURATION,
	MT.DV_ANNUALIZED_FLG,
	MT.RU_SERVICE_CONTRACT_START_DTM,
	MT.RU_SERVICE_CONTRACT_END_DTM,
	MT.ANNUITY_TYPE,
	MT.ANNUITY_MONTH,
	MT.ANNUITY_WEEK,
MT.BKGS_END_WEEK,
MT.PER_MONTH_AMT  *    (MOD(MT.DV_CONTRACT_DURATION, 12) )   ANNUITY_AMT/*SVAKULAB*/,
	MT.DV_FMV_FLG,
	MT.ADJUSTMENT_CODE,
	MT.ACQUISITION_ORDER_ORIGIN_CD,
MT.ACQUISITION_ROLE
	FROM
	{{ source('raw', 'WI_BKGS_MSR_ATY_PRDT_AMR_XAAS') }} MT
	WHERE
	RTRIM(   ANNUITY_TYPE)  in (COLLATE('Software', 'en-ci-rtrim'))
AND (BOOKINGS_MEASURE_KEY, BKGS_MEASURE_TRANS_TYPE_CODE, BOOKINGS_PROCESS_DATE, COLLATE(ANNUITY_TYPE, 'en-ci-rtrim'), SALES_TERRITORY_KEY, SALES_REP_NUMBER, ANNUITY_MONTH)
IN (
		SELECT
			BOOKINGS_MEASURE_KEY,
			BKGS_MEASURE_TRANS_TYPE_CODE,
			BOOKINGS_PROCESS_DATE,
			COLLATE(ANNUITY_TYPE, 'en-ci-rtrim'),
			SALES_TERRITORY_KEY,
			SALES_REP_NUMBER,
			MAX(ANNUITY_MONTH)  ANNUITY_MONTH
							FROM
			{{ source('raw', 'WI_BKGS_MSR_ATY_PRDT_AMR_XAAS') }}
		WHERE
			RTRIM( ANNUITY_TYPE)  in (COLLATE('Software', 'en-ci-rtrim'))
							GROUP BY BOOKINGS_MEASURE_KEY  ,BKGS_MEASURE_TRANS_TYPE_CODE  ,BOOKINGS_PROCESS_DATE,SALES_TERRITORY_KEY,SALES_REP_NUMBER,ANNUITY_TYPE )